//! The 48 lvim themes, as GPUI colours.
//!
//! **The files are not touched by this port.** They are the editor's own
//! resolved highlight groups, generated by lvim-colorscheme, and they were the
//! point of a long argument: `text.primary` is `Normal.fg`, at whatever contrast
//! the editor has it (`#5e8888` on base dark, 3.86:1), because a client that
//! sits beside the editor all day has to be the same colour as the editor.
//! Only the code that READS them moved from egui to GPUI; every value is the
//! same byte it was.
//!
//! Corners stay square — there is no radius anywhere in this client.

use std::collections::BTreeMap;
use std::path::PathBuf;

use gpui::{rgb, Rgba};
use serde::Deserialize;

#[allow(dead_code)] // the file is the contract; see the note in the generator
#[derive(Debug, Clone, Deserialize)]
pub struct Theme {
    pub name: String,
    #[serde(default)]
    pub style: String,
    #[serde(default)]
    pub dark: bool,
    pub surface: Surface,
    pub text: Text,
    pub accent: Accent,
    #[serde(default)]
    pub syntax: Syntax,
    #[serde(default, rename = "match")]
    pub match_: Match,
    pub grid: Grid,
    #[serde(default)]
    pub palette: BTreeMap<String, String>,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Surface {
    /// `Normal.bg` — the buffer: the grid and the editor.
    pub base: String,
    /// `NormalSB.bg` — the editor's own side panel.
    pub panel: String,
    /// `Pmenu.bg` — a popup list's body, the nearest thing to a card.
    pub raised: String,
    /// `NormalFloat.bg` — a float: dialogs.
    pub overlay: String,
    /// `StatusLine.bg`.
    #[serde(default)]
    pub status: String,
    /// `CursorLine.bg` — the row under the pointer.
    #[serde(default)]
    pub hover: String,
    /// `PmenuSel.bg` — a selected entry in a LIST (not selected text).
    #[serde(default)]
    pub selected: String,
    /// `WinSeparator.fg`, which on every lvim style equals its own background:
    /// the editor draws no line between windows, and neither does this.
    pub border: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Text {
    pub primary: String,
    /// `Comment`, deliberately not `LineNr`.
    pub muted: String,
    #[serde(default)]
    pub title: String,
    pub inverted: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Accent {
    pub primary: String,
    pub secondary: String,
    pub success: String,
    pub warning: String,
    pub error: String,
    pub info: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Default, Deserialize)]
pub struct Syntax {
    #[serde(default)]
    pub keyword: String,
    #[serde(default)]
    pub string: String,
    #[serde(default)]
    pub number: String,
    #[serde(default)]
    pub comment: String,
    #[serde(default)]
    pub function: String,
    #[serde(default)]
    pub operator: String,
    #[serde(default)]
    pub identifier: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Default, Deserialize)]
pub struct Match {
    #[serde(default)]
    pub bg: String,
    #[serde(default)]
    pub fg: String,
}

#[allow(dead_code)]
#[derive(Debug, Clone, Deserialize)]
pub struct Grid {
    pub header_bg: String,
    pub header_fg: String,
    pub row_alt: String,
    pub selection_bg: String,
    pub selection_fg: String,
    pub null_fg: String,
    /// `LineNr` — the row-number column and nothing else.
    #[serde(default)]
    pub line_nr: String,
}

/// Parse `#rrggbb`, or `None` when it is not one.
pub fn parse_hex(s: &str) -> Option<Rgba> {
    let t = s.trim().trim_start_matches('#');
    if t.len() != 6 {
        return None;
    }
    u32::from_str_radix(t, 16).ok().map(rgb)
}

/// Parse `#rrggbb`. One unreadable value costs one colour, never the theme.
pub fn hex(s: &str, fallback: Rgba) -> Rgba {
    parse_hex(s).unwrap_or(fallback)
}

/// The two roots of the fallback chain, read from the BUILT-IN theme rather
/// than written as literals here.
///
/// Every other role falls back to another role; these two had nowhere left to
/// fall, and were a hard-coded `#20272b` and `#ffffff` in the working code.
/// A number in the source is a colour that did not come from the theme, which
/// is the one rule this client has about colour. The built-in theme is the
/// generated `LvimBase_dark` byte for byte, so it is guaranteed complete and
/// valid — meaning a default has somewhere to come from without a literal.
///
/// Resolved once: `builtin()` parses a TOML document, and doing that per call
/// of `base()` would parse it thousands of times a frame.
/// Both `expect` rather than falling back again, and that is the point: there
/// is no fourth place for a colour to come from, so inventing one would mean
/// writing the literal this removed. The built-in theme is checked in, parsed by
/// `builtin()` (which already panics on a malformed document) and asserted
/// against the editor's own groups by a test — a build in which these fail is a
/// build whose theme file is broken, and that should stop, not dim.
fn root_bg() -> Rgba {
    static ROOT: std::sync::OnceLock<Rgba> = std::sync::OnceLock::new();
    *ROOT.get_or_init(|| {
        parse_hex(&Theme::builtin().surface.base).expect("the built-in theme's surface.base must be #rrggbb")
    })
}

fn root_fg() -> Rgba {
    static ROOT: std::sync::OnceLock<Rgba> = std::sync::OnceLock::new();
    *ROOT.get_or_init(|| {
        parse_hex(&Theme::builtin().text.primary).expect("the built-in theme's text.primary must be #rrggbb")
    })
}

impl Theme {
    // Each role falls back to a surface that is certainly there, so a theme
    // missing one is dimmer, never broken. Written out rather than generated:
    // the fallback CHAIN is the interesting part and a macro hides it.
    pub fn base(&self) -> Rgba {
        hex(&self.surface.base, root_bg())
    }
    pub fn panel(&self) -> Rgba {
        hex(&self.surface.panel, self.base())
    }
    pub fn raised(&self) -> Rgba {
        hex(&self.surface.raised, self.base())
    }
    pub fn overlay(&self) -> Rgba {
        hex(&self.surface.overlay, self.panel())
    }
    pub fn status(&self) -> Rgba {
        hex(&self.surface.status, self.panel())
    }
    pub fn hover(&self) -> Rgba {
        hex(&self.surface.hover, self.raised())
    }
    pub fn selected(&self) -> Rgba {
        hex(&self.surface.selected, self.hover())
    }
    pub fn border(&self) -> Rgba {
        hex(&self.surface.border, self.raised())
    }
    pub fn fg(&self) -> Rgba {
        hex(&self.text.primary, root_fg())
    }
    pub fn muted(&self) -> Rgba {
        hex(&self.text.muted, self.fg())
    }
    pub fn title(&self) -> Rgba {
        hex(&self.text.title, self.muted())
    }
    pub fn inverted(&self) -> Rgba {
        hex(&self.text.inverted, self.base())
    }
    pub fn accent(&self) -> Rgba {
        hex(&self.accent.primary, self.fg())
    }
    pub fn success(&self) -> Rgba {
        hex(&self.accent.success, self.accent())
    }
    pub fn warning(&self) -> Rgba {
        hex(&self.accent.warning, self.accent())
    }
    pub fn error(&self) -> Rgba {
        hex(&self.accent.error, self.accent())
    }
    pub fn header_bg(&self) -> Rgba {
        hex(&self.grid.header_bg, self.raised())
    }
    pub fn header_fg(&self) -> Rgba {
        hex(&self.grid.header_fg, self.fg())
    }
    pub fn row_alt(&self) -> Rgba {
        hex(&self.grid.row_alt, self.base())
    }
    pub fn selection_bg(&self) -> Rgba {
        hex(&self.grid.selection_bg, self.selected())
    }
    pub fn selection_fg(&self) -> Rgba {
        hex(&self.grid.selection_fg, self.fg())
    }
    pub fn null_fg(&self) -> Rgba {
        hex(&self.grid.null_fg, self.muted())
    }
    pub fn line_nr(&self) -> Rgba {
        hex(&self.grid.line_nr, self.muted())
    }

    /// The colour a type badge is drawn in. Mapped from the badge word rather
    /// than from a driver name, so a type this client has never heard of lands
    /// on the neutral ink instead of nothing.
    pub fn badge(&self, kind: &str) -> Rgba {
        match kind {
            "string" => hex(&self.syntax.string, self.fg()),
            "int" | "num" => hex(&self.syntax.number, self.fg()),
            "bool" => hex(&self.syntax.keyword, self.fg()),
            "null" => self.null_fg(),
            "object" | "array" => hex(&self.syntax.function, self.accent()),
            "oid" => hex(&self.syntax.identifier, self.accent()),
            "date" => hex(&self.syntax.keyword, self.accent()),
            _ => self.muted(),
        }
    }

    /// The built-in theme: byte for byte the generated LvimBase_dark, so the
    /// window looks the same before a theme is installed and after.
    pub fn builtin() -> Theme {
        toml::from_str(include_str!("builtin_theme.toml")).expect("the built-in theme must parse")
    }
}

/// Where themes are looked for, in order.
pub fn theme_dirs() -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Some(d) = std::env::var_os("LODE_THEME_DIR") {
        out.push(PathBuf::from(d));
    }
    if let Some(d) = std::env::var_os("XDG_CONFIG_HOME") {
        out.push(PathBuf::from(d).join("lode/themes"));
    }
    if let Some(h) = std::env::var_os("HOME") {
        out.push(PathBuf::from(h).join(".config/lode/themes"));
    }
    out
}

/// Every theme file found, by name. The first directory wins a clash.
pub fn discover() -> BTreeMap<String, PathBuf> {
    let mut found: BTreeMap<String, PathBuf> = BTreeMap::new();
    for dir in theme_dirs() {
        let Ok(entries) = std::fs::read_dir(&dir) else { continue };
        for e in entries.flatten() {
            let p = e.path();
            if p.extension().and_then(|s| s.to_str()) != Some("toml") {
                continue;
            }
            let Some(stem) = p.file_stem().and_then(|s| s.to_str()) else { continue };
            found.entry(stem.to_string()).or_insert(p);
        }
    }
    found
}

pub fn load(path: &std::path::Path) -> anyhow::Result<Theme> {
    let text = std::fs::read_to_string(path)?;
    toml::from_str(&text).map_err(|e| anyhow::anyhow!("{}: {e}", path.display()))
}

/// The theme to start with: `$LODE_THEME`, else the first found, else built in.
pub fn pick() -> (String, Theme) {
    pick_named(None)
}

/// The theme to start with, preferring one by name.
///
/// `want` is what the session remembered. It comes FIRST because it is the most
/// recent thing the person actually chose; `$LODE_THEME` is next because it is
/// deliberate too but set once; and the first file found is a fallback rather
/// than a choice. The session's theme was being saved and never read — a picker
/// that forgets is a picker that has to be used every morning.
pub fn pick_named(want: Option<&str>) -> (String, Theme) {
    let themes = discover();
    for name in want.map(str::to_string).into_iter().chain(std::env::var("LODE_THEME").ok()) {
        if let Some(p) = themes.get(&name) {
            if let Ok(t) = load(p) {
                return (name, t);
            }
        }
    }
    for (name, path) in &themes {
        if let Ok(t) = load(path) {
            return (name.clone(), t);
        }
    }
    let t = Theme::builtin();
    (t.name.clone(), t)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hex_parses_and_falls_back() {
        assert_eq!(hex("#20272b", rgb(0xff0000)).r, rgb(0x20272b).r);
        assert_eq!(hex("20272b", rgb(0xff0000)).g, rgb(0x20272b).g);
        assert_eq!(hex("nope", rgb(0xff0000)).r, rgb(0xff0000).r);
        assert_eq!(hex("#12345", rgb(0xff0000)).r, rgb(0xff0000).r);
    }

    /// The port must not have changed a single value: this is the editor's
    /// `Normal`, `Comment`, `StatusLine`, `CursorLine`, `PmenuSel` and `Visual`.
    #[test]
    fn the_builtin_theme_is_still_the_editors_base_dark() {
        let t = Theme::builtin();
        assert_eq!(t.surface.base, "#20272b", "Normal.bg");
        assert_eq!(t.text.primary, "#5e8888", "Normal.fg — NOT lifted for contrast");
        assert_eq!(t.text.muted, "#5b7d7e", "Comment.fg");
        assert_eq!(t.surface.status, "#1e2529", "StatusLine.bg");
        assert_eq!(t.surface.hover, "#2a373d", "CursorLine.bg");
        assert_eq!(t.surface.selected, "#243037", "PmenuSel.bg");
        assert_eq!(t.grid.selection_bg, "#22292d", "Visual.bg");
        assert_eq!(t.grid.selection_fg, t.text.primary, "Visual sets no fg");
        assert_eq!(t.grid.line_nr, "#2a373d", "LineNr.fg");
        // `surface.border` is the one deliberate departure from a literal
        // source group: `WinSeparator` equals its own background on all 48
        // styles (the editor draws no line between windows), and this client
        // puts a tree, a result, a console and a task list in ONE frame, where
        // no outline at all reads as one surface. It takes `LineNr` — the
        // quietest ink the editor really paints.
        assert_eq!(t.surface.border, "#2a373d", "LineNr.fg, used as the border");
    }

    /// The embedded copy must BE the generated file.
    ///
    /// It is a copy, not a symlink, because a crate has to build without the
    /// colorscheme checkout beside it. A copy can go stale, and it did: the
    /// generator moved `surface.border` from `WinSeparator` to `LineNr` and the
    /// embedded theme kept the old `#1e2529` for five days. This test is the
    /// thing that would have said so — it compares byte for byte when the
    /// checkout is there, and skips when it is not.
    #[test]
    fn the_embedded_theme_is_byte_for_byte_the_generated_one() {
        let Some(dir) = std::env::var_os("LODE_THEME_DIR") else {
            eprintln!("skipped: set LODE_THEME_DIR to compare against the generated themes");
            return;
        };
        let generated = std::path::PathBuf::from(dir).join("LvimBase_dark.toml");
        let Ok(text) = std::fs::read_to_string(&generated) else {
            eprintln!("skipped: no {} to compare against", generated.display());
            return;
        };
        assert_eq!(
            text,
            include_str!("builtin_theme.toml"),
            "crates/lode-ui/src/builtin_theme.toml is stale — copy {} over it",
            generated.display()
        );
    }

    /// The last two colours in the working code came from a literal; now they
    /// come from the built-in theme. The test says exactly that, so putting a
    /// number back would fail here rather than be noticed by eye.
    #[test]
    fn the_root_fallbacks_come_from_the_builtin_theme() {
        let b = Theme::builtin();
        assert_eq!(root_bg(), parse_hex(&b.surface.base).unwrap());
        assert_eq!(root_fg(), parse_hex(&b.text.primary).unwrap());
        // And a theme whose two roots are MISSING falls back to exactly those,
        // rather than to white on black. Built by blanking the built-in theme
        // rather than by hand-writing a skeleton: a skeleton drifts the moment a
        // role is added, and then this test fails for the wrong reason.
        let mut empty = Theme::builtin();
        empty.surface.base = String::new();
        empty.text.primary = String::new();
        assert_eq!(empty.base(), parse_hex(&b.surface.base).unwrap());
        assert_eq!(empty.fg(), parse_hex(&b.text.primary).unwrap());
    }

    /// Every real generated theme must load through the ported reader too.
    /// Pointed at the generator's output with `LODE_THEME_DIR`.
    #[test]
    fn every_generated_theme_loads() {
        let Some(dir) = std::env::var_os("LODE_THEME_DIR") else {
            eprintln!("skipped: set LODE_THEME_DIR to check the real themes");
            return;
        };
        let found = discover();
        assert!(!found.is_empty(), "no .toml themes in {dir:?}");
        for (name, path) in &found {
            let t = load(path).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(&t.name, name);
            assert_eq!(t.dark, !t.style.ends_with("_light"));
            assert_eq!(t.grid.selection_fg, t.text.primary);
            // A sentinel must never survive: an unparsed colour would be a
            // silent magenta in the window.
            for (what, v) in [
                ("surface.base", &t.surface.base),
                ("surface.status", &t.surface.status),
                ("surface.selected", &t.surface.selected),
                ("text.primary", &t.text.primary),
                ("text.title", &t.text.title),
                ("grid.line_nr", &t.grid.line_nr),
            ] {
                assert_ne!(hex(v, rgb(0x010203)).r, rgb(0x010203).r, "{name}: {what} = {v:?}");
            }
        }
        eprintln!("checked {} generated theme(s)", found.len());
    }

    #[test]
    fn a_badge_colour_is_never_nothing() {
        let t = Theme::builtin();
        for k in ["string", "int", "num", "bool", "null", "object", "array", "oid", "date", "whatever"] {
            let c = t.badge(k);
            assert!(c.a > 0.0, "{k} must have a visible colour");
        }
    }
}
